import { ArrowRight } from "lucide-react";
import { CategoryIcon } from "@/components/ui/CategoryIcon";
import { cn } from "@/lib/utils";
import type { Category, OpportunityType } from "@/lib/types";

interface CategoryCardProps {
  category: Category;
  className?: string;
}

const ICON_MAP: Record<OpportunityType | string, { bg: string; color: string }> = {
  internship:  { bg: "bg-pink-50", color: "text-pink-600" },
  job:         { bg: "bg-slate-50", color: "text-slate-700" },
  competition: { bg: "bg-emerald-50", color: "text-emerald-600" },
  hackathon:   { bg: "bg-indigo-50", color: "text-indigo-600" },
  scholarships: { bg: "bg-blue-50", color: "text-blue-600" },
  workshops:   { bg: "bg-orange-50", color: "text-orange-600" },
  college_fest: { bg: "bg-purple-50", color: "text-purple-600" },
  cultural:    { bg: "bg-red-50", color: "text-red-600" },
};

export function CategoryCard({ category, className }: CategoryCardProps) {
  const { type, label, description, iconKey } = category;
  const c = ICON_MAP[type] || { bg: "bg-slate-50", color: "text-slate-600" };
  
  return (
    <a
      href={`#${type}`}
      className={cn(
        "group relative flex min-w-[140px] flex-col items-center text-center justify-between rounded-xl border border-slate-100 bg-white p-5 transition-all duration-200 hover:-translate-y-1 hover:border-slate-200 hover:shadow-md",
        className
      )}
      aria-label={`Explore ${label}`}
    >
      <div className="flex flex-col items-center gap-3">
        <div className={cn("flex h-12 w-12 items-center justify-center rounded-lg shadow-sm border border-slate-100/50", c.bg, c.color)}>
          <CategoryIcon iconKey={iconKey} size={20} />
        </div>
        
        <div className="flex flex-col gap-1">
          <h3 className="text-[13px] font-bold text-slate-900">{label}</h3>
          <p className="text-[11px] text-slate-500 leading-snug">{description}</p>
        </div>
      </div>
    </a>
  );
}
