import { Briefcase, User, Zap, Trophy, GraduationCap, Calendar } from "lucide-react";
import type { CategoryIconKey } from "@/lib/types";
import { cn } from "@/lib/utils";

interface CategoryIconProps {
  iconKey: CategoryIconKey;
  className?: string;
  size?: number;
}

const ICON_MAP: Record<CategoryIconKey, React.ComponentType<{ size?: number; className?: string }>> = {
  briefcase:  Briefcase,
  user:       User,
  zap:        Zap,
  trophy:     Trophy,
  graduation: GraduationCap,
  calendar:   Calendar,
};

export function CategoryIcon({ iconKey, className, size = 20 }: CategoryIconProps) {
  const Icon = ICON_MAP[iconKey];
  return <Icon size={size} className={cn("flex-shrink-0", className)} />;
}
